        /// <summary>The difficulty readouts (the original's fmt functions).</summary>
        public static string Fmt(string k, float v)
        {
            string s = v.ToString("0.##");
            switch (k)
            {
                case "dEnemyHp": return s + "× (" + (v <= 0.8f ? "soft" : v <= 1.2f ? "normal" : v <= 2f ? "tough" : v <= 3.5f ? "very tough" : v <= 5.5f ? "juggernaut" : "nightmare") + ")";
                case "dEnemyDmg": return s + "× (" + (v <= 0.6f ? "light" : v <= 1.15f ? "normal" : v <= 1.8f ? "heavy" : "brutal") + ")";
                case "dEnemyAcc": return s + "× spread (" + (v <= 0.4f ? "deadly" : v <= 0.75f ? "sharp" : v <= 1.2f ? "normal" : "sloppy") + ")";
                case "dYouHp": return s + "× (" + (v <= 0.75f ? "fragile" : v <= 1.2f ? "normal" : v <= 1.8f ? "sturdy" : "iron") + ")";
                default: return s;
            }
        }
